import android.content.Context
import androidx.room.Database
import androidx.room.Room
import androidx.room.RoomDatabase
import androidx.room.migration.Migration
import androidx.sqlite.db.SupportSQLiteDatabase
import com.example.fridgetracker.model.Product

@Database(entities = [Product::class], version = 3, exportSchema = false)
abstract class AppDatabase : RoomDatabase() {
 abstract fun productDao(): ProductDao

 companion object {
 @Volatile private var INSTANCE: AppDatabase? = null
 val MIGRATION_1_3: Migration = object : Migration(1, 3) {
 override fun migrate(database: SupportSQLiteDatabase) {
 database.execSQL("ALTER TABLE Product ADD COLUMN category TEXT NOT NULL DEFAULT ''")
 }
 }
 fun getInstance(context: Context): AppDatabase =
 INSTANCE ?: synchronized(this) {
 val inst = Room.databaseBuilder(
 context.applicationContext,
 AppDatabase::class.java,
 "fridge_db"
 ).addMigrations(MIGRATION_1_3)
 .build()
 INSTANCE = inst
 inst
 }
 }
}"},{"role":"tool","name":"read_file","tool_call_id":"toolu_bdrk_01VeXvdkTy1u22BU18faUV7R","content":"package com.example.fridgetracker.model

